174: fn handle_system_log(this_program_str: &str, log: &str) -> (Option<String>, bool) {
175:     if log.starts_with(&format!("Program {this_program_str} log:")) {
176:         (Some(this_program_str.to_string()), false)
177:     } else if log.contains("invoke") {
178:         (Some("cpi".to_string()), false) // Any string will do.
179:     } else {
180:         let re = Regex::new(r"^Program (.*) success*$").unwrap();
181:         if re.is_match(log) {
182:             (None, true)
183:         } else {
184:             (None, false)
185:         }
186:     }
