/// Parses a batch of program logs for a single transaction and emits any
/// matching events through the provided callback.
fn process_logs<T: anchor_lang::Event + anchor_lang::AnchorDeserialize>(
    self_program_str: &str,
    ctx: &EventContext,
    logs: &[String],
    f: &impl Fn(&EventContext, T),
) {
    let mut logs = logs;
    if logs.is_empty() {
        return;
    }
    if let Ok(mut execution) = Execution::new(&mut logs) {
        for l in logs {
            // Parse the log.
            let (event, new_program, did_pop) = {
                if self_program_str == execution.program() {
                    handle_program_log(self_program_str, l).unwrap_or_else(|e| {
                        println!("Unable to parse log: {e}");
                        std::process::exit(1);
                    })
                } else {
                    let (program, did_pop) = handle_system_log(self_program_str, l);
                    (None, program, did_pop)
                }
            };
            // Emit the event.
            if let Some(e) = event {
                f(ctx, e);
            }
            // Switch program context on CPI.
            if let Some(new_program) = new_program {
                execution.push(new_program);
            }
            // Program returned.
            if did_pop {
                execution.pop();
            }
        }
    }
}

